const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Simulate update_reservation_flights logic:
// 1. The new flight is FL40B96D on 2026-09-15 in economy
// 2. It's a new flight (different date), so we look up the price from dates_json
// 3. Economy price on 2026-09-15 = 199
// 4. Old flight price (from reservation) = 0
// 5. Fare diff = (199 * 1 passenger) - (0 * 1 passenger) = 199
// 6. Charge 199 to cc_2402ef91

// Get current reservation
const res = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C10BB4'\").get();

// Get the flight data for the new date
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FL40B96D' AND source_skill = 'tau2Airline'\").get();
const datesData = JSON.parse(flight.dates_json);
const sept15Data = datesData['2026-09-15'];

// New economy price
const newPrice = sept15Data.prices.economy;  // 199
console.log('New flight economy price:', newPrice);

// Old price from reservation
const oldFlights = JSON.parse(res.flights_json);
const oldPrice = oldFlights[0].price || 0;
console.log('Old flight price in reservation:', oldPrice);

// Passengers
const passengers = JSON.parse(res.passengers_json);
const numPassengers = passengers.length;  // 1
console.log('Number of passengers:', numPassengers);

// Fare difference
const fareDiff = (newPrice * numPassengers) - (oldPrice * numPassengers);
console.log('Fare difference:', fareDiff);

// Update the reservation
const newFlightsJson = JSON.stringify([{
  flight_id: 'FL40B96D',
  origin: 'SFO',
  destination: 'LAS',
  date: '2026-09-15',
  price: newPrice
}]);

// Update payment history
const paymentHistory = JSON.parse(res.payment_history_json);
if (fareDiff !== 0) {
  paymentHistory.push({
    payment_id: 'cc_2402ef91',
    amount: fareDiff
  });
}
const newPaymentHistory = JSON.stringify(paymentHistory);

// Update the seat count (decrement available economy seats on new date)
sept15Data.available_seats.economy -= numPassengers;
datesData['2026-09-15'] = sept15Data;
const newDatesJson = JSON.stringify(datesData);

// Write updates
db.prepare(\"UPDATE flight_bookings SET flights_json = ?, payment_history_json = ?, fare_difference = ? WHERE booking_id = 'C10BB4'\").run(
  newFlightsJson, newPaymentHistory, fareDiff
);

// Update flight seat availability
db.prepare(\"UPDATE flights SET dates_json = ? WHERE flight_id = 'FL40B96D' AND source_skill = 'tau2Airline'\").run(newDatesJson);

// Verify
const updated = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C10BB4'\").get();
console.log('\\n=== UPDATED RESERVATION ===');
console.log('Booking ID:', updated.booking_id);
console.log('Flights:', updated.flights_json);
console.log('Payment history:', updated.payment_history_json);
console.log('Fare difference:', updated.fare_difference);
console.log('Cabin class:', updated.cabin_class);
console.log('Status:', updated.status);
console.log('\\nUpdate successful!');
"
